    TaskStrictFieldTypedTargetService(EnterpriseAccess access,TaskStrictFieldTypedStore store,StrictComparisonCodec codec,TaskStrictFieldTypedActors actors,TaskFieldTargetBasis tasks,StrictComparisonRunScope scopes,StrictComparisonAuthority authority,StrictDecimalEvidenceService decimals,TaskStrictFieldContextService contexts,StrictComparisonPolicyService policies,StrictFieldComparisonSchema schema,TaskStrictFieldTextEvidence texts,FormalCapabilityIdentityAuthority roles){this.roles=roles;this.texts=texts;this.access=access;this.store=store;this.codec=codec;this.actors=actors;this.tasks=tasks;this.scopes=scopes;this.authority=authority;this.decimals=decimals;this.contexts=contexts;this.policies=policies;this.schema=schema;}
    public JsonNode author(ApplicationSessionIdentity.Verified subject,String context,String project,String key,byte[] bytes)throws Exception{
        var request=codec.bind(bytes,TaskStrictFieldTypedProtocol.Author.class);var tree=codec.tree(request);if("2.0.0".equals(request.schemaVersion()))com.ruoyi.medical.contracts.SchemaCatalogue.fromClasspath().validate("strict-field-typed-v2",tree,"Author");
        return access.execute(subject,a->checked(()->{StrictComparisonAuthority.human(a,context);var author=actors.witness(a,project,WRITE);var old=store.replay(a,project,Kind.TARGET,key,tree);if(old!=null)return require(a,project,old.id(),old.digest(),null).receipt();
            String id=UUID.randomUUID().toString();var resolved=resolve(a,project,id,request,null);var body=codec.tree(Map.of("request",request,"manifest",resolved.manifest));
            var row=store.appendAt(a,project,Kind.TARGET,null,key,tree,body,codec.tree(Map.of("author",author,"witness",resolved.witness)),id);
            one(store.db.update("INSERT INTO task_strict_field_typed_state(tenant_id,project_id,revision_id,revision,status,decision_id,schema_version,schema_manifest_sha256,created_by,created_at,classification) SELECT tenant_id,project_id,revision_id,1,'DRAFT',NULL,schema_version,schema_manifest_sha256,created_by,created_at,classification FROM task_strict_field_typed_revision WHERE tenant_id=? AND project_id=? AND revision_id=?",a.context().tenant_id(),project,id));actors.require(a,project,WRITE,author);return row.receipt();
        }));
    }
    public JsonNode read(ApplicationSessionIdentity.Verified subject,String context,String project,String id){return access.execute(subject,a->checked(()->{StrictComparisonAuthority.human(a,context);authority.project(a,project,READ);var row=store.read(a,project,Kind.TARGET,id);var proof=require(a,project,id,row.digest(),null);return codec.tree(Map.of("manifest",proof.manifest(),"receipt",proof.receipt(),"state",state(a,project,id)));}));}
    public JsonNode baseline(ApplicationSessionIdentity.Verified subject,String context,String project,String id){return access.execute(subject,a->checked(()->{StrictComparisonAuthority.human(a,context);authority.project(a,project,READ);var row=store.read(a,project,Kind.TARGET,id);var proof=require(a,project,id,row.digest(),null);var baseline=baseline(a,project,row,proof);return codec.tree(Map.of("baseline",baseline,"baseline_sha256",codec.hash(baseline)));}));}
    public JsonNode decide(ApplicationSessionIdentity.Verified subject,String context,String project,String id,String key,byte[] bytes)throws Exception{
        var request=codec.bind(bytes,TaskStrictFieldTypedProtocol.Decide.class);var envelope=codec.tree(Map.of("revision_id",id,"decision",request));
        return access.execute(subject,a->checked(()->{StrictComparisonAuthority.human(a,context);var approver=actors.witness(a,project,APPROVE);var row=store.read(a,project,Kind.TARGET,id);if(!request.schemaVersion().equals(row.request().path("schema_version").asText()))mismatch();
            if(a.actorId().equals(row.receipt().required("created_by").asText()))deny();var previous=store.replay(a,project,Kind.TARGET_DECISION,key,envelope);if(previous!=null){if(!id.equals(previous.parentId()))mismatch();return previous.receipt();}
            var live=require(a,project,id,row.digest(),null);var baseline=baseline(a,project,row,live);var state=state(a,project,id);if(!request.expectedRevision().equals(text(state,"revision")))throw new TenantAccessException(ErrorCode.REVISION_CONFLICT);
            if(!request.contentSha256().equals(row.digest())||!request.baselineSha256().equals(codec.hash(baseline)))throw new TenantAccessException(ErrorCode.SCOPE_STALE);
            String status=switch(request.decision()){case APPROVE->"APPROVED";case REJECT->"REJECTED";case DISABLE->"DISABLED";};if(status.equals(text(state,"status"))||"DRAFT".equals(text(state,"status"))&&"DISABLED".equals(status))throw new TenantAccessException(ErrorCode.REVISION_CONFLICT);
            String revision=PermissionSchema.next(request.expectedRevision());var body=codec.tree(Map.of("revision_id",id,"content_sha256",row.digest(),"revision",revision,"status",status,"baseline",baseline,"decision",request,"approver",approver));var saved=store.append(a,project,Kind.TARGET_DECISION,id,key,envelope,body,baseline);
            one(store.db.update("UPDATE task_strict_field_typed_state SET revision=?,status=?,decision_id=? WHERE tenant_id=? AND project_id=? AND revision_id=? AND revision=?",revision,status,saved.id(),a.context().tenant_id(),project,id,request.expectedRevision()));live.requireUnchanged();actors.require(a,project,APPROVE,approver);store.advance(a);return saved.receipt();
        }));
    }
    Verified requireHuman(EnterpriseAccess.Admission a,String project,String id,String digest)throws Exception{var proof=require(a,project,id,digest,null);proof.requireApproved();return proof;}
    Verified requireFixedRun(TaskNodeProductionAuthority.Verified production,String id,String digest)throws Exception{var proof=require(production.admission(),production.projectId(),id,digest,production);proof.requireApproved();return proof;}
    private Verified require(EnterpriseAccess.Admission a,String project,String id,String digest,TaskNodeProductionAuthority.Verified run)throws Exception{
        authority.project(a,project,READ);var row=store.read(a,project,Kind.TARGET,id);if(!digest.equals(row.digest()))mismatch();var request=codec.bind(row.request(),TaskStrictFieldTypedProtocol.Author.class);if("2.0.0".equals(request.schemaVersion()))com.ruoyi.medical.contracts.SchemaCatalogue.fromClasspath().validate("strict-field-typed-v2",row.request(),"Author");if(!row.request().equals(row.body().required("request")))mismatch();var resolved=resolve(a,project,id,request,run);
        if(!resolved.manifest.equals(row.body().required("manifest"))||!row.receipt().required("created_by").asText().equals(row.authority().required("author").required("actor").asText()))mismatch();actors.require(a,project,WRITE,row.authority().required("author"));return new Verified(a,project,row,request,resolved,run);
    }
    private record Resolved(JsonNode manifest,JsonNode witness){}
