    public final class Verified{
        private final EnterpriseAccess.Admission a;private final String project;private final Row row;private final TaskStrictFieldTypedProtocol.Author request;private final Resolved resolved;private final TaskNodeProductionAuthority.Verified run;
        private Verified(EnterpriseAccess.Admission a,String project,Row row,TaskStrictFieldTypedProtocol.Author request,Resolved resolved,TaskNodeProductionAuthority.Verified run){this.a=a;this.project=project;this.row=row;this.request=request;this.resolved=resolved;this.run=run;}
        public void requireUnchanged()throws Exception{var fresh=require(a,project,row.id(),row.digest(),run);if(!resolved.witness.equals(fresh.resolved.witness))throw new TenantAccessException(ErrorCode.SCOPE_STALE);}
        public void requireApproved()throws Exception{requireUnchanged();approved(a,project,row);}
        public JsonNode manifest(){return resolved.manifest.deepCopy();}public JsonNode receipt(){return row.receipt().deepCopy();}public String revisionId(){return row.id();}public String digest(){return row.digest();}public TaskStrictFieldTypedProtocol.Author request(){return request;}
        EnterpriseAccess.Admission admission(){return a;}JsonNode witness(){return resolved.witness.deepCopy();}String project(){return project;}
        PermissionProtocol.Basis decision()throws Exception{var d=approved(a,project,row);return new PermissionProtocol.Basis(d.id(),d.digest());}
    }
    private JsonNode baseline(EnterpriseAccess.Admission a,String project,Row row,Verified live)throws Exception{return codec.tree(Map.of("revision_id",row.id(),"content_sha256",row.digest(),"state",state(a,project,row.id()),"source_authority",live.witness(),"author",row.authority().required("author")));}
    private Map<String,Object> state(EnterpriseAccess.Admission a,String project,String id){var row=single(store.db.queryForList("SELECT * FROM task_strict_field_typed_state WHERE tenant_id=? AND project_id=? AND revision_id=? FOR UPDATE",a.context().tenant_id(),project,id));var original=single(store.db.queryForList("SELECT * FROM task_strict_field_typed_revision WHERE tenant_id=? AND project_id=? AND revision_id=? FOR UPDATE",a.context().tenant_id(),project,id));for(String key:List.of("tenant_id","project_id","revision_id","schema_version","schema_manifest_sha256","created_by","created_at","classification"))if(!Objects.equals(row.get(key),original.get(key)))mismatch();var result=new HashMap<String,Object>();for(String key:List.of("revision","status","decision_id"))result.put(key,row.get(key));return result;}
    private Row approved(EnterpriseAccess.Admission a,String project,Row row)throws Exception{
        var state=state(a,project,row.id());if(!"APPROVED".equals(text(state,"status"))||state.get("decision_id")==null)throw new TenantAccessException(ErrorCode.CONDITION_UNKNOWN);var decision=store.read(a,project,Kind.TARGET_DECISION,text(state,"decision_id"));var body=decision.body();var supplied=codec.bind(body.required("decision"),TaskStrictFieldTypedProtocol.Decide.class);
        if(!row.id().equals(decision.parentId())||!row.id().equals(body.required("revision_id").asText())||!row.digest().equals(body.required("content_sha256").asText())||!row.digest().equals(supplied.contentSha256())||!"APPROVED".equals(body.required("status").asText())||supplied.decision()!=StrictComparisonProtocol.Decision.APPROVE||!text(state,"revision").equals(body.required("revision").asText())||!text(state,"revision").equals(PermissionSchema.next(supplied.expectedRevision()))||!codec.hash(body.required("baseline")).equals(supplied.baselineSha256())||row.receipt().required("created_by").equals(decision.receipt().required("created_by"))||!decision.receipt().required("created_by").asText().equals(body.required("approver").required("actor").asText()))mismatch();actors.require(a,project,WRITE,row.authority().required("author"));actors.require(a,project,APPROVE,body.required("approver"));return decision;
    }
    private static StrictComparisonPolicyDefinition.Context context(TaskStrictFieldTypedProtocol.Context c){return new StrictComparisonPolicyDefinition.Context(c.mode()==TaskStrictFieldTypedProtocol.Mode.GLOBAL?StrictComparisonPolicyDefinition.ContextMode.GLOBAL:StrictComparisonPolicyDefinition.ContextMode.SCOPED,c.ids());}
    private static ContextState state(TaskStrictFieldTypedProtocol.Context c){return c.mode()==TaskStrictFieldTypedProtocol.Mode.GLOBAL?ContextState.KNOWN_GLOBAL:ContextState.KNOWN_SCOPED;}
    private static void deny(){throw new TenantAccessException(ErrorCode.ACCESS_DENIED);}private static <T>T checked(ThrowingSupplier<T> action){return action.get();}
